#!/usr/bin/env python3
"""Generate a single Go file with an exact scip-go occurrence count."""

import argparse
from pathlib import Path

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("count", type=int, nargs="?", default=100_000)
args = parser.parse_args()
if args.count < 3:
    parser.error("count must be at least 3 (the package and two declarations)")

lines = [
    "// Code generated by generate.py; DO NOT EDIT.",
    "",
    "package fixture",
    "",
    "// Value is referenced throughout the file for hover, definition, and highlight testing.",
    "const Value = 1",
    "",
    "// Values contains enough references to exceed the code graph loading limit.",
    "var Values = []int{",
]
# scip-go 0.2.7 emits definitions for fixture, Value, and Values, but not int.
references = args.count - 3
for start in range(0, references, 20):
    lines.append("\t" + ", ".join(["Value"] * min(20, references - start)) + ",")
lines.append("}")
Path(__file__).with_name("occurrences.go").write_text("\n".join(lines) + "\n")
print(f"Generated occurrences.go for {args.count:,} SCIP occurrences")
